class Solution {
public:
    int minimumChairs(string s) {
        int cur = 0, ans = 0;
        for (char ch : s) {
            if (ch == 'E') {
                cur++;
                ans = max(ans, cur);
            } else {
                cur--;
            }
        }
        return ans;
    }
};

class Solution {
    public int minimumChairs(String s) {
        int cur = 0, ans = 0;
        for (int i = 0; i < s.length(); ++i) {
            char ch = s.charAt(i);
            if (ch == 'E') {
                cur++;
                ans = Math.max(ans, cur);
            } else {
                cur--;
            }
        }
        return ans;
    }
}

var minimumChairs = function(s) {
    let cur = 0, ans = 0;
    for (const ch of s) {
        if (ch === 'E') {
            cur++;
            ans = Math.max(ans, cur);
        } else {
            cur--;
        }
    }
    return ans;
};
